B.am=s([],t.zr)
B.Xg=s(["Th..Thank you, Mateo. I..I owe you my life...","The words grow distant as exhaustion pulls you back into darkness."],t.s)
B.OC=new A.cw("Close your eyes","intro_pass_out_to_spanish_home",!0,!1)
B.Z3=s([B.OC],t.u)
