B.OX=new A.cO("Narrator",B.Uw)
B.Vl=s(["Thank god... I feared the worst. What happened to you?"],t.s)
B.OD=new A.cw("Continue","intro_player_remembers",!0,!1)
B.Yp=s([B.OD],t.u)
B.Pq=new A.ci(B.am,B.Vl,null,null,null,B.Yp)
B.Yy=s([B.Pq],t.J)
B.OY=new A.cO("Stranger",B.Yy)
B.Zb=s(["I was on my way to the docks when I found you. I was sure you were dead...","The doctor has been by to check on you. Your body, he says, will heal, but he cannot explain your memory loss.","Now that you are awake, do you remember anything about what happened to you?"],t.s)
B.Ot=new A.cw("Try to remember","intro_recall_prince_face",!0,!1)
B.Zd=s([B.Ot],t.u)
B.Pj=new A.ci(B.am,B.Zb,null,null,null,B.Zd)
B.Zq=s([B.Pj],t.J)
B.OZ=new A.cO("Mateo",B.Zq)
B.WK=s(["Welcome aboard, sailor. I am Captain Lorenzo, and I assign bounties to crews bold enough to earn them.","A bounty is a promise: I name the target, you bring back proof, and the reward is yours.","I have a first contract waiting. Will you accept it?"],t.s)
B.Oy=new A.cw("Accept first bounty","accept_italy_first_bounty",!0,!0)
B.Oo=new A.cw("Not yet","close_dialogue",!0,!0)
B.Y_=s([B.Oy,B.Oo],t.u)
B.P9=new A.ci(B.am,B.WK,null,null,"italy_first_bounty",B.Y_)
B.YV=s(["Redfin is defeated. You have done Italy a service, captain.","As promised, your bounty is 500 gold."],t.s)
B.hE=new A.wu(1,"readyToTurnIn")
B.Ol=new A.cw("Claim bounty","claim_italy_first_bounty",!0,!0)
B.Z6=s([B.Ol],t.u)
B.Pb=new A.ci(B.am,B.YV,"italy_first_bounty",B.hE,null,B.Z6)
B.XG=s(["Redfin will trouble these waters no more. Spend your reward wisely, captain.","Another Redfin has been sighted. Will you take the next contract?"],t.s)
B.jR=new A.wu(2,"completed")
B.Ow=new A.cw("Accept another bounty","accept_italy_first_bounty",!0,!0)
