B.Pe=new A.ci(B.am,B.XG,"italy_first_bounty",B.jR,null,B.Xd)
B.Uz=s(["Your target is Redfin, a vicious crimson beast seen in open waters.","It is rarely sighted. Keep fighting at sea and watch for its red scales."],t.s)
B.dn=new A.wu(0,"active")
B.Pm=new A.ci(B.am,B.Uz,"italy_first_bounty",B.dn,null,B.dQ)
